    for i in range(N):
        sequence.append(2**A[i])
        while len(sequence) > 1 and sequence[-1] == sequence[-2]:
            sequence.pop()
            sequence[-1] = sequence[-1] + sequence[-1]
            if len(sequence) > 1 and sequence[-1] == sequence[-2]:
                sequence.pop()
                sequence[-1] = sequence[-1] + sequence[-1]
