def find_island_area(H, W, Y, A):
    def sink(i, j, level):
        if i < 0 or i >= H or j < 0 or j >= W or A[i][j] > level:
            return
        A[i][j] = 0
        for(i, j) in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]:
            sink(i, j, level + 1)

    for year in range(Y):
        for i in range(H):
            for j in range(W):
                if A[i][j] <= year:
                    sink(i, j, year + 1)
    return sum(A[i][j] for i in range(H) for j in range(W))

