    capturedquares = set()
    for a, b in pieces:
        for i in range(1, N+1):
            for j in range(1, N+1):
                if i == a or j == b or i + j == a + b or i - j == a - b:
                    capturedquares.add((i, j))
    total_squares = N * N
    empty_squares = len(total_squares) - len(capturedquares)
    return empty_squares

