class Solution:
    def countInterestingSubarrays(self, nums: List[int], modulo: int, k: int) -> int:
        count = 0
        prefix_sum = [0] * modulo
        for num in nums:
            prefix_sum[num % modulo] += 1
        for i in range(modulo):
            if prefix_sum[i] > 0:
                for j in range(i + 1, modulo):
                    if prefix_sum[j] > 0:
                        if (prefix_sum[i] * prefix_sum[j]) % modulo == k:
                            count += prefix_sum[i] * prefix_sum[j]
        return count

