def circular_shift(N, M, S, C):
    for i in range(1, M + 1):
        start = 0
        end = 0
        while end < N:
            if C[end] == i:
                start += 1
                end += 1
            else:
                end += 1
        if start < end:
            temp = S[start:end]
            S[start:end] = S[end] + S[start:end - temp]
            start = end
            end += 1
    return S

