def count_operations(N, H):
    A = [0] * (N + 1)
    A[0] = 1
    for i in range(1, N + 1):
        while A[i - 1] > A[i] and A[i - 1]>H[i]:
            A[i - 1] -= 1
            A[i] += 1
    return A[1:]

