def find_star_levels(N, edges):
    graph = {}
    for u, v in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append(v)
        graph[v].append(u)

    leaves = [0
    for i in range(1, N + 1) if len(graph[i]) == 1]

    while len(graph) > 2:
        new_leaves = []
        for leaf in leaves:
            neighbor = graph[leaf][0]
            graph[neighbor].remove(leaf)
            if len(graph[neighbor]) == 1:
                new_leaves.append(neighbor)
        leaves = new_leaves

    levels = []
    for leaf in leaves:
