    def maxPalindromesAfterOperations(self, words: List[str]) -> int:
        def is_palindrome(word):
            return word == word[::-1]

        count = 0
        for word in words:
            if is_palindrome(word):
                count += 1

        for = {}
        for word in words:
            if is_palindrome(word):
                for[word] = 1
            else:
                for i in range(len(word)):
