class Solution:
    def countValidSelections(self, nums: List[int]) -> int:
        def dfs(curr, direction):
            if curr < 0 or curr >= len(nums):
                return 0
            if nums[curr] == 0:
                return 1
            if nums[curr] > 0:
                nums[curr] -= 1
                return dfs(curr + 1, 1) + dfs(curr - 1, -1)
            else:
                return 0

        count = 0
        for i in range(len(nums)):
            if nums[i] == 0:
                count += dfs(i, 1) + dfs(i, -1)

        return count

