def min_operations(N, S, T):
    dp = [[0] * (N + 2) for _ in range(N + 2)]
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            dp[i][j] = min[i - 1][j - 1] + (S[i - 1] != T[j - 1])
            for k in range(i - 1, 0):
                dp[i][j] = min(dp[i][j], dp[k][j - 1] + (S[k - 1] != T[j - 1]))
    return dp[N][N]

