class Solution:
    def shortestBeautifulSubstring(self, s: str, k: int) -> str:
        n = len(s)
        left = 0
        right = 0
        one_count = 0
        min_len = float('inf')
        min_str = ""

        while right < n:
            if s[right] == '1':
                one_count += 1

            while one_count > k:
                if s[left] == '1':
                    one_count -= 1
                left += 1

            if one_count == k:
                if right - left + 1 < min_len:
                    min_len = right - left + 1
                    min_str = s[left:right+1]

            right += 1

        return min_str

