    def numberOfAlternatingGroups(self, colors: List[int], queries: List[List[int]]) -> List[int]:
        n = len(colors)
        def count_alternating_groups(start, size):
            count = 0
            for i in range(start, start + size):
                if (i + 1) % n != start and colors[i] != colors[i + 1]:
                    count += 1
            return count

        def change_color(index, color):
            colors[index] = color
            count = 0
            for i in range(index, index + size):
                if (i + 1) % n != index and colors[i] != colors[i + 1]:
                    count += 1
            return count

        result = []
        for query in queries:
            if query[0] == 1:
                result.append(count_alternating_groups(query[1], query[1]))
            elif query[0] == 2:
                count = change_color(query[1], query[2])
                result.append(count)

        return result

