    def calculate_inversion_number(P):
        count = 0
        for i in range(N):
            for j in range(i + 1, N):
                if P[i] > P[j]:
                    count += 1
        return count

    def apply_operation(P, k):
        for i in range(k - 1):
            if P[i] > P[i + 1]:
                P[i], P[i + 1] = P[i + 1], P[i]

    results = []
    for k in A:
        apply_operation(P, k)
        results.append(calculate_inversion_number(P))

    return results

