    edges = []
    for i in range(q):
        for j in range(1, n + 1):
            for k in range(j, n + 1):
                edges.append((q[i][k - 1], n + i, k))
    edges.sort(key=lambda x: x[0])
    cost = 0
    parent = [i for i in range(n + q)]
    for i in range):
        if parent[i] != i:
            parent[i] = find(parent[i])
        return parent[i]
    def union(x, y, cost):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            parent[root_x] = root_y
            return cost
        return 0
    for cost, x, y in edges:
        if union(x, y, cost):
            cost += cost
    return cost

