    result = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if i == 0 or i == N - 1 or j == 0 or j == N - 1:
                result[i][j] = A[i][j]
            else:
                result[i][j] = A[i][j - 1] if j > 0 else A[i - 1][j]
    return result

