class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        n = len(nums)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]

        def is_valid(start, end):
            if end - start == 1:
                return True
            if prefix_sum[end] - prefix_sum[start] >= m:
                return True
            for i in range(start + 1, end):
                if is_valid(start, i) and is_valid(i, end):
                    return True
            return False

        for i in range(n):
            if is_valid(0, i + 1):
                return True
        return False

