        def count_set_bits(n):
            return bin(n).count('1')

        def can_swap(i, j):
            return count_set_bits(nums[i]) == count_set_bits(nums[j])

        def dfs(index):
            if index == len(nums):
                return True
            for i in range(index, len(nums)):
                if can_swap(index, i):
                    nums[index], nums[i], nums[i], nums[index] = nums[index], nums[i], nums[i], nums[index]
                    if dfs(index + 1):
                        return True
                    nums[index], nums[i], nums[i], nums[index] = nums[index], nums[i], nums[i], nums[index]
            return False

        return dfs(0)

